// Short reading combinations. Assessment is performed by the teacher, never by speech recognition.
export const READING_CHECK_LETTERS=[['alif','ا','Алиф'],['ba','ب','Ба'],['ta','ت','Та'],['tha','ث','Са'],['jim','ج','Джим'],['ha','ح','Ха'],['kha','خ','Хо'],['dal','د','Даль'],['dhal','ذ','Заль'],['ra','ر','Ро'],['zay','ز','За'],['sin','س','Син'],['shin','ش','Шин'],['sad','ص','Сод'],['dad','ض','Дод'],['tta','ط','То'],['za','ظ','Зо'],['ayn','ع','Айн'],['ghayn','غ','Гойн'],['fa','ف','Фа'],['qaf','ق','Коф'],['kaf','ك','Каф'],['lam','ل','Лям'],['mim','م','Мим'],['nun','ن','Нун'],['heh','ه','Ха'],['waw','و','Уау'],['ya','ي','Йа']];
export const READING_REASONS={letter:'Буква',vowel:'Огласовка',joining:'Соединение букв',sukun:'Сукун',pace:'Темп чтения',other:'Другое'};
export const readingLetter=id=>READING_CHECK_LETTERS.find(row=>row[0]===id)||null;
export function readingExamples(letterId,count=10){const row=readingLetter(letterId);if(!row)return[];const c=row[1];if(letterId==='mim')return['أَمْ','إِمْ','أُمْ','أَمْرُ','أَمَرُ','مَ','مِ','مُ','أَمَ','إِمَ','أُمَ','أَمِ','أَمُ','مَرَ','رَمَ'].slice(0,count);if(letterId==='alif')return Array.from({length:count},(_,i)=>['أَ','إِ','أُ','ا'][i%4]);return[c+'َ',c+'ِ',c+'ُ','أَ'+c+'ْ','إِ'+c+'ْ','أُ'+c+'ْ','أَ'+c+'َ','إِ'+c+'َ','أُ'+c+'َ','أَ'+c+'ِ','إِ'+c+'ِ','أُ'+c+'ِ','أَ'+c+'ُ','إِ'+c+'ُ','أُ'+c+'ُ'].slice(0,count);}
export function normalizeReadingCheck(value){
 if(value==null)return null;const row=readingLetter(value.letterId);if(!row||![10,15].includes(value.count)||!Array.isArray(value.prompts)||value.prompts.length!==value.count)throw Error('Выберите пройденную букву и 10 или 15 сочетаний.');
 const prompts=value.prompts.map(text=>{if(typeof text!=='string')throw Error('Добавьте арабские сочетания.');const normalized=text.normalize('NFC').trim();if(!normalized||normalized.length>24||!(/^[\u0621-\u063A\u0641-\u0652\u0670\u0671 ]+$/u).test(normalized)||!(letterIdHas(normalized,row)))throw Error('В каждом сочетании нужны арабские буквы и огласовки с выбранной буквой.');return normalized;});
 return{version:1,letterId:row[0],count:value.count,prompts,dueBeforeNextLesson:true};
}
function letterIdHas(text,row){return row[0]==='alif'?/[اأإآ]/u.test(text):text.includes(row[1]);}
export function normalizeReadingReview(value,check){if(!check)return null;const normalized=normalizeReadingCheck(check);if(!Array.isArray(value)||value.length!==normalized.count)throw Error('Отметьте чтение каждого сочетания.');const marks=value.map(mark=>{if(!mark||typeof mark.correct!=='boolean'||mark.reason!=null&&!Object.hasOwn(READING_REASONS,mark.reason))throw Error('Отметьте чтение каждого сочетания.');return{correct:mark.correct,reason:mark.correct?null:mark.reason||'other'};});const mistakes=marks.flatMap((mark,index)=>mark.correct?[]:[{index,prompt:normalized.prompts[index],reason:mark.reason}]);return{count:normalized.count,correctCount:normalized.count-mistakes.length,mistakeCount:mistakes.length,marks,difficulties:mistakes};}
